<script setup lang="ts">
import {commerce,cartCount,updateQuantity,removeCart,prepareCheckout,openStore} from '../../stores/commerce';import {getProduct,getArt,openProduct} from '../../data/catalog';import PageHeader from '../../components/PageHeader.vue';import ProductVisual from '../../components/ProductVisual.vue';import LineIcon from '../../components/LineIcon.vue';
function remove(key:string){uni.showModal({title:'移除这件商品？',content:'之后仍可从商城重新选择。',success:r=>{if(r.confirm)removeCart(key)}})}
</script>
<template><view class="screen cart-page"><PageHeader label="购物车"/><view class="page-content"><text class="page-title">装下你的喜欢。</text><text class="page-subtitle">{{cartCount?'已选择 '+cartCount+' 件联名产品':'下一份喜欢，在路上。'}}</text><view v-if="!commerce.cart.length" class="empty-state"><LineIcon name="cart" :size="64"/><text>购物车还是空的</text><text class="body-text">先去看看，哪幅画与你有共鸣。</text><button role="button" class="primary-button" @click="openStore">逛逛联名商店</button></view><view v-else><view v-for="item in commerce.cart" :key="item.key" class="cart-item"><button role="button" class="cart-product" @click="openProduct(item.productId,item.artId)" :aria-label="`查看${getProduct(item.productId).name}`"><view class="cart-thumb"><ProductVisual :product="{...getProduct(item.productId),art:item.artId}"/></view><view class="cart-copy"><text class="cart-name">{{getProduct(item.productId).name}}</text><text>《{{getArt(item.artId).name}}》</text><text>{{item.spec}}</text><text class="cart-price">售价待公布</text></view></button><view class="cart-controls"><button role="button" class="remove-button" @click="remove(item.key)">移除</button><view class="stepper"><button role="button" @click="updateQuantity(item.key,item.quantity-1)" :disabled="item.quantity===1" aria-label="减少数量">−</button><text>{{item.quantity}}</text><button role="button" @click="updateQuantity(item.key,item.quantity+1)" :disabled="item.quantity===99" aria-label="增加数量">＋</button></view></view></view><text class="muted-note cart-note">这是设计演示。作品、规格和价格待正式确认，结算不会产生真实付款。</text></view></view><view v-if="commerce.cart.length" class="checkout-bar"><view><text>共 {{cartCount}} 件</text><text class="muted-note">演示选购 · 无真实扣款</text></view><button role="button" class="primary-button" @click="prepareCheckout(commerce.cart,true)">模拟结算</button></view></view></template>
<style scoped>
.cart-page{background:#fff;padding-bottom:calc(104px + env(safe-area-inset-bottom))}.cart-item{padding:24px 0;border-bottom:1px solid var(--color-line)}.cart-product{display:flex;width:100%;padding:0;background:none;text-align:left;gap:20px;align-items:center}.cart-thumb{width:112px;height:136px;overflow:hidden;border-radius:16px;flex:none}.cart-thumb :deep(.product-visual){height:136px}.cart-thumb :deep(.pouch){transform:scale(.65) rotate(-4deg)}.cart-thumb :deep(.shirt){transform:scale(.6)}.cart-copy{display:flex;flex-direction:column;gap:6px;font-size:var(--font-footnote);line-height:1.5;color:var(--color-secondary);min-width:0}.cart-name{font-size:var(--font-body);font-weight:600;color:var(--color-text)}.cart-price{color:var(--color-accent)}.cart-controls{display:flex;align-items:center;justify-content:space-between;margin-top:16px}.remove-button{font-size:var(--font-footnote);color:var(--color-muted);background:none;padding:8px 0;min-height:44px}.cart-note{margin-top:24px}.checkout-bar{position:fixed;bottom:0;left:0;right:0;max-width:480px;margin:auto;display:flex;gap:16px;justify-content:space-between;align-items:center;padding:16px var(--page-gutter) calc(16px + env(safe-area-inset-bottom));background:#fff;border-top:1px solid var(--color-line)}.checkout-bar>view>text:first-child{font-size:var(--font-body);font-weight:600;display:block}.checkout-bar .primary-button{min-width:140px}.checkout-bar .muted-note{font-size:var(--font-caption)}
